    public Task<List<Course>> GetCoursesAsync(CourseFilterCriteria? filter = null)
    {
        var query = _courses.AsEnumerable();

        if (filter is not null)
        {
            if (!string.IsNullOrWhiteSpace(filter.SearchText))
            {
                var search = filter.SearchText.Trim();
                query = query.Where(c =>
                    c.Title.Contains(search, StringComparison.OrdinalIgnoreCase) ||
                    c.CourseCode.Contains(search, StringComparison.OrdinalIgnoreCase) ||
                    c.InstructorName.Contains(search, StringComparison.OrdinalIgnoreCase) ||
                    c.Description.Contains(search, StringComparison.OrdinalIgnoreCase));
            }

            if (!string.IsNullOrWhiteSpace(filter.DepartmentCode))
            {
                query = query.Where(c => c.DepartmentCode == filter.DepartmentCode);
            }

            if (filter.Credits.HasValue)
            {
                query = query.Where(c => c.Credits == filter.Credits.Value);
            }
        }

        return Task.FromResult(query.OrderBy(c => c.DepartmentCode).ThenBy(c => c.CourseCode).ToList());
    }

    public Task<Course?> GetCourseByIdAsync(int id)
    {
        return Task.FromResult(_courses.FirstOrDefault(c => c.Id == id));
    }

    public Task<List<Course>> GetFeaturedCoursesAsync()
    {
        return Task.FromResult(_courses.Where(c => c.IsFeatured).ToList());
    }

    public Task<List<Department>> GetDepartmentsAsync()
    {
        return Task.FromResult(_departments.ToList());
    }

    public Task<bool> SubmitEnrollmentRequestAsync(EnrollmentRequest request)
    {
        var course = _courses.FirstOrDefault(c => c.Id == request.CourseId);
        if (course is null || course.CurrentEnrollment >= course.MaxEnrollment)
            return Task.FromResult(false);

        // In a real app, this would persist to a database
        return Task.FromResult(true);
    }
}
