```razor
<div class="card mb-4 shadow-sm">
    <div class="card-body">
        <div class="row g-3 align-items-end">
            <div class="col-md-5">
                <label for="search" class="form-label fw-semibold">Search</label>
                <input id="search" type="text" class="form-control" placeholder="Search by title, code, or instructor…"
                       value="@Filter.SearchText"
                       @oninput="OnSearchInput" />
            </div>
            <div class="col-md-3">
                <label for="department" class="form-label fw-semibold">Department</label>
                <select id="department" class="form-select" value="@Filter.DepartmentCode"
                        @onchange="OnDepartmentChanged">
                    <option value="">All Departments</option>
                    @foreach (var dept in Departments)
                    {
                        <option value="@dept.Code">@dept.Name</option>
                    }
                </select>
            </div>
            <div class="col-md-2">
                <label for="credits" class="form-label fw-semibold">Credits</label>
                <select id="credits" class="form-select" value="@(Filter.Credits?.ToString() ?? "")"
                        @onchange="OnCreditsChanged">
                    <option value="">Any</option>
                    <option value="3">3 credits</option>
                    <option value="4">4 credits</option>
                </select>
            </div>
            <div class="col-md-2">
                <button class="btn btn-outline-secondary w-100" @onclick="ClearFilters">
                    Clear Filters
                </button>
            </div>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public CourseFilterCriteria Filter { get; set; } = new();

    [Parameter, EditorRequired]
    public List<Department> Departments { get; set; } = new();

    [Parameter]
    public EventCallback<CourseFilterCriteria> OnFilterChanged { get; set; }

    private async Task OnSearchInput(ChangeEventArgs e)
    {
        Filter.SearchText = e.Value?.ToString() ?? string.Empty;
        await OnFilterChanged.InvokeAsync(Filter);
    }

    private async Task OnDepartmentChanged(ChangeEventArgs e)
    {
        Filter.DepartmentCode = e.Value?.ToString() ?? string.Empty;
        await OnFilterChanged.InvokeAsync(Filter);
    }

    private async Task OnCreditsChanged(ChangeEventArgs e)
    {
        var val = e.Value?.ToString();
        Filter.Credits = int.TryParse(val, out var credits) ? credits : null;
        await OnFilterChanged.InvokeAsync(Filter);
    }

    private async Task ClearFilters()
    {
        Filter.SearchText = string.Empty;
        Filter.DepartmentCode = string.Empty;
        Filter.Credits = null;
        await OnFilterChanged.InvokeAsync(Filter);
    }
}
