**Enroll.razor**:
```razor
@page "/enroll"
@inject ICatalogService CatalogService

<PageTitle>Enrollment Request</PageTitle>

<h1 class="mb-4">📝 Enrollment Request</h1>
<p class="text-muted mb-4">Fill out the form below to request enrollment in a course. All fields marked with * are required.</p>

@if (submitted)
{
    @if (success)
    {
        <div class="alert alert-success">
            <h4 class="alert-heading">Request Submitted!</h4>
            <p>Your enrollment request has been received. You will be notified by email once it has been processed.</p>
            <hr />
            <a href="courses" class="btn btn-primary">Browse More Courses</a>
            <button class="btn btn-outline-secondary ms-2" @onclick="ResetForm">Submit Another Request</button>
        </div>
    }
    else
    {
        <div class="alert alert-danger">
            <h4 class="alert-heading">Request Failed</h4>
            <p>We could not process your enrollment request. The course may be full or unavailable. Please try another course or contact the registrar.</p>
            <button class="btn btn-outline-danger" @onclick="ResetForm">Try Again</button>
        </div>
    }
}
else
{
    <div class="row">
        <div class="col-lg-8">
            <EditForm Model="model" OnValidSubmit="HandleSubmit" FormName="enrollment">
                <DataAnnotationsValidator />
                <ValidationSummary class="text-danger mb-3" />

                <div class="mb-3">
                    <label for="studentName" class="form-label fw-semibold">Full Name *</label>
                    <InputText id="studentName" class="form-control" @bind-Value="model.StudentName" placeholder="e.g., Jane Smith" />
                    <ValidationMessage For="() => model.StudentName" class="text-danger" />
                </div>

                <div class="mb-3">
                    <label for="studentId" class="form-label fw-semibold">Student ID *</label>
                    <InputText id="studentId" class="form-control" @bind-Value="model.StudentId" placeholder="e.g., STU12345" />
                    <ValidationMessage For="() => model.StudentId" class="text-danger" />
                </div>

                <div class="mb-3">
                    <label for="courseId" class="form-label fw-semibold">Course *</label>
                    <InputSelect id="courseId" class="form-select" @bind-Value="model.CourseId">
                        <option value="0">— Select a course —</option>
                        @foreach (var course in availableCourses)
                        {
                            <option value="@course.Id">@course.CourseCode — @course.Title (@course.Credits cr)</option>
                        }
                    </InputSelect>
                    <ValidationMessage For="() => model.CourseId" class="text-danger" />
                </div>

                <div class="mb-3">
                    <label for="comments" class="form-label fw-semibold">Comments (optional)</label>
                    <InputTextArea id="comments" class="form-control" @bind-Value="model.Comments" rows="3"
                                   placeholder="Any additional information for the registrar…" />
                </div>

                <button type="submit" class="btn btn-success">
                    Submit Enrollment Request
                </button>
                <a href="courses" class="btn btn-outline-secondary ms-2">Cancel</a>
            </EditForm>
        </div>
    </div>
}

@code {
    private EnrollmentRequest model = new();
    private List<Course> availableCourses = new();
    private bool submitted;
    private bool success;

    [SupplyParameterFromQuery(Name = "courseId")]
    public int? PreselectedCourseId { get; set; }

    protected override async Task OnInitializedAsync()
    {
        availableCourses = await CatalogService.GetCoursesAsync();

        if (PreselectedCourseId.HasValue)
        {
            model.CourseId = PreselectedCourseId.Value;
        }
    }

    private async Task HandleSubmit()
    {
        success = await CatalogService.SubmitEnrollmentRequestAsync(model);
        submitted = true;
    }

    private void ResetForm()
    {
        model = new EnrollmentRequest();
        submitted = false;
        success = false;
    }
}
```

